const std = @import("std");

pub const FlyMyAIPredictException = error{
    HttpError,
    JsonParseError,
    Base64DecodeError,
    FileWriteError,
    PredictFailed,
    OutOfMemory,
    UriParseError,
};

const Payload = struct {
    prompt: []const u8,
    aspect_ratio: ?[]const u8,
    image_size: ?[]const u8,
    image: ?[]const u8,
    image1: ?[]const u8,
    image2: ?[]const u8,
    image3: ?[]const u8,
    image4: ?[]const u8,
    image5: ?[]const u8,
    image6: ?[]const u8,
    image7: ?[]const u8,
    image8: ?[]const u8,
    image9: ?[]const u8,
    image10: ?[]const u8,
    image11: ?[]const u8,
    image12: ?[]const u8,
    image13: ?[]const u8,
};

const RequestBody = struct {
    model: []const u8,
    payload: Payload,
};

const ResponseData = struct {
    output_data: struct {
        image: []const u8,
    },
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const apikey = "fly-***";
    const model = "flymyai/nano-banana-2";

    const payload = Payload{
        .prompt = "A cat attempts a daring jump across a gap, but hilariously miscalculates.",
        .aspect_ratio = null,
        .image_size = null,
        .image = null,
        .image1 = null,
        .image2 = null,
        .image3 = null,
        .image4 = null,
        .image5 = null,
        .image6 = null,
        .image7 = null,
        .image8 = null,
        .image9 = null,
        .image10 = null,
        .image11 = null,
        .image12 = null,
        .image13 = null,
    };

    const req_body = RequestBody{
        .model = model,
        .payload = payload,
    };

    const predict_result = executePredict(allocator, apikey, req_body);
    if (predict_result) |image_encoded| {
        defer allocator.free(image_encoded);

        const Decoder = std.base64.standard.Decoder;
        const decoded_len = Decoder.calcSizeForSlice(image_encoded) catch |err| {
            std.debug.print("FlyMyAIPredictException: {any}\n", .{err});
            return err;
        };
        const decoded_image = allocator.alloc(u8, decoded_len) catch |err| {
            std.debug.print("FlyMyAIPredictException: {any}\n", .{err});
            return err;
        };
        defer allocator.free(decoded_image);

        Decoder.decode(decoded_image, image_encoded) catch |err| {
            std.debug.print("FlyMyAIPredictException: {any}\n", .{err});
            return err;
        };

        const file = std.fs.cwd().createFile("image_output.jpg", .{ .truncate = true }) catch |err| {
            std.debug.print("FlyMyAIPredictException: {any}\n", .{err});
            return err;
        };
        defer file.close();

        file.writeAll(decoded_image) catch |err| {
            std.debug.print("FlyMyAIPredictException: {any}\n", .{err});
            return err;
        };

        std.debug.print("Saved image_output.jpg\n", .{});
    } else |err| {
        std.debug.print("{any}\n", .{err});
        return err;
    }
}

fn executePredict(allocator: std.mem.Allocator, apikey: []const u8, req_body: RequestBody) ![]const u8 {
    var client = std.http.Client{ .allocator = allocator };
    defer client.deinit();

    const uri = try std.Uri.parse("");

    const json_req = try std.json.stringifyAlloc(allocator, req_body, .{});
    defer allocator.free(json_req);

    var auth_buf: [128]u8 = undefined;
    const auth_str = try std.fmt.bufPrint(&auth_buf, "Bearer {s}", .{apikey});

    var buf: [4096]u8 = undefined;
    var req = try client.open(.POST, uri, .{
        .server_header_buffer = &buf,
        .extra_headers = &.{
            .{ .name = "Content-Type", .value = "application/json" },
            .{ .name = "Authorization", .value = auth_str },
        },
    });
    defer req.deinit();

    req.transfer_encoding = .{ .content_length = json_req.len };
    try req.send();
    try req.writeAll(json_req);
    try req.finish();
    try req.wait();

    if (req.response.status != .ok) {
        return FlyMyAIPredictException.PredictFailed;
    }

    var body = std.ArrayList(u8).init(allocator);
    defer body.deinit();
    try req.reader().readAllArrayList(&body, 1024 * 1024 * 50);

    const parsed = try std.json.parseFromSlice(ResponseData, allocator, body.items, .{ .ignore_unknown_fields = true });
    defer parsed.deinit();

    return try allocator.dupe(u8, parsed.value.output_data.image);
}
